1	// ============================================================================
2	// tests/hw/tp_loopback_binding.cu — JIT binding for the TENSOR-PARALLEL
3	// LOOPBACK gate (design §5.1/§5.2 via §7; task #25 phase-2, Lane C).
4	//
5	// WHAT IT PROVES (driven by tests/hw/test_tp_loopback.py, single GPU):
6	// the full Megatron column→row TP pair — col-parallel GEMM, local gelu,
7	// row-parallel partial GEMM, PUBLISH → rendezvous → FIXED-ORDER ascending-pe
8	// fp32 all-reduce (fwd point ②), and the conjugate backward (row-parallel dX
9	// local, col-parallel dX partial → all-reduce, bwd point ②') plus the
10	// exact-slice dW/db shards — running on TP=P VIRTUAL ranks in ONE grid over
11	// the LoopbackTransport symmetric heap, using the PRODUCTION wgmma tile GEMMs
12	// (dectc_gemm_fwd_f32 / dectc_gemm_dx_f32 — the same engine, staging, fp32
13	// accumulate as the L3-TC megakernel; ffn shapes d=128, dff=512, kTileM=128).
14	//
15	// THE TRANSPORT SWAP POINT: the kernel below is written against the
16	// tp_transport.cuh concept. Re-pointing `LoopbackTransport` → `NvshmemTransport`
17	// (8×H100 window, -DSG_HAS_NVSHMEM) changes NO math in this file — that is the
18	// design §5.3/§5.4 seam, and the residual GPU-window task.
19	//
20	// HONESTY: the loopback is NOT fake success — the host asserts
21	//   (a) all P virtual ranks produced BIT-IDENTICAL reduced outputs,
22	//   (b) 3 reruns are BIT-IDENTICAL (A/A/A),
23	//   (c) the TP+transport result == a SERIAL chunked-order reference BIT-EXACT
24	//       (proves the transport contributes exactly zero numerical effect),
25	//   (d) every dW/db shard == the corresponding slice of the UNSHARDED dW/db
26	//       BIT-EXACT (the slice-exactness property tp_layer.cuh documents),
27	//   (e) vs the unsharded full-K reference within the campaign parity tol
28	//       (the chunk-reassociation delta, reported, not asserted bitwise).
29	//
30	// JIT-built via torch.utils.cpp_extension.load into /workspace/.torch_ext —
31	// owns its PYBIND11_MODULE; setup.py's _owns_extension_module excludes it from
32	// the production _ops build (same discipline as sharded_optimizer_binding.cu).
33	// ============================================================================
34	
35	#include <torch/extension.h>
36	#include <c10/cuda/CUDAStream.h>
37	#include <cuda_runtime.h>
38	#include <cuda_bf16.h>
39	#include <cstdint>
40	
41	#include "csrc/fused/sm_90/tp_layer.cuh"        // TP math + transport + dectc GEMMs
42	
43	namespace {
44	
45	using namespace sg::fused;          // GridBarrier
46	using namespace sg::fused::sm90;    // dec::, dectc::
47	namespace tp = sg::fused::sm90::tp;
48	
49	constexpr int kM   = dectc::kTileM;     // 128 token rows (one production tile)
50	constexpr int kD   = dec::kD;           // 128
51	constexpr int kDff = dec::kDff;         // 512
52	constexpr int kBlk = 256;               // the megakernel CTA shape (2 warpgroups)
53	
54	// Shared-memory mirror of DecTcSmem's GEMM ring (sA/sB/red) — same sizes the
55	// production kernel hands the dectc GEMMs.
56	struct TpSmem {
57	    static constexpr int kAtomsPerSlot =
58	        (dectc::kAtomsM < dectc::kDecMaxIL) ? dectc::kAtomsM : dectc::kDecMaxIL;
59	    __nv_bfloat16 sA[dectc::kDecTcStages * kAtomsPerSlot * 64 * 16];
60	    __nv_bfloat16 sB[dectc::kDecTcStages * SG_TUNED_TILE_N * 16];
61	};
62	
63	// ─────────────────────────────────────────────────────────────────────────
64	//  Device buffers bundle (raw pointers; all fp32 unless noted).
65	//  Shard buffers are DENSE concatenations over ranks:
66	//    W0s [P][dff/P, d]   b0s [P][dff/P]   W1s [P][d, dff/P]
67	//  Per-PE scratch/outputs are [P][...] concatenations.
68	// ─────────────────────────────────────────────────────────────────────────
69	struct TpArgs {
70	    const __nv_bfloat16* X;      // [M, d]   tile input (bf16, like X_x1)
71	    const __nv_bfloat16* dY1;    // [M, d]   output adjoint (bf16, like dY_ff2)
72	    const float* W0s; const float* b0s; const float* W1s;   // dense shards
73	    const float* b1;             // [d] replicated
74	    float* heap;                 // [P * 2 * M*d] loopback symmetric heap
75	    __nv_bfloat16* pre;          // [P][M, dff/P] bf16 (ff0pre mirror)
76	    __nv_bfloat16* G;            // [P][M, dff/P] bf16 (X_gact mirror)
77	    float* dG;                   // [P][M, dff/P] fp32
78	    __nv_bfloat16* dY0;          // [P][M, dff/P] bf16 (dY_ff0 mirror)
79	    float* Y1;                   // [P][M, d] reduced fwd output, per-PE copy
80	    float* dX;                   // [P][M, d] reduced bwd dX, per-PE copy
81	    float* dW0;                  // [P][dff/P, d]  (== concat: [dff, d])
82	    float* db0;                  // [P][dff/P]     (== concat: [dff])
83	    float* dW1;                  // [P][d, dff/P]
84	    float* db1;                  // [P][d] (replicated — every PE computes it)
85	    int P;
86	};
87	
88	// ─────────────────────────────────────────────────────────────────────────
89	//  THE TP=P LOOPBACK KERNEL. grid = P CTAs (1 CTA per virtual PE — one tile in
90	//  flight per PE, the persistent-kernel shape); block = 256. The GridBarrier
91	//  over the whole grid is the cross-PE rendezvous (LoopbackTransport contract).
92	// ─────────────────────────────────────────────────────────────────────────
93	__global__ void __launch_bounds__(kBlk)
94	tp_loopback_block_kernel(TpArgs a, unsigned* g_arrived, unsigned* g_generation) {
95	    __shared__ TpSmem sm;
96	    const int P  = a.P;
97	    const int F  = kDff / P;                 // local feature width
98	    GridBarrier bar(g_arrived, g_generation, (unsigned)gridDim.x);
99	    tp::LoopbackTransport tr{a.heap, tp::tp_heap_stride_floats(1), P,
100	                             tp::LoopbackTransport::pe_of_cta(blockIdx.x, gridDim.x, P)};
101	    const int pe = tr.my_pe();
102	    const int64_t slot_part = 0;                          // publish slot
103	    const int64_t slot_n    = tp::tp_tile_slot_floats();  // M*d floats
104	
105	    // Per-PE views.
106	    __nv_bfloat16* pre  = a.pre + (int64_t)pe * kM * F;
107	    __nv_bfloat16* G    = a.G   + (int64_t)pe * kM * F;
108	    float*         dG   = a.dG  + (int64_t)pe * kM * F;
109	    __nv_bfloat16* dY0  = a.dY0 + (int64_t)pe * kM * F;
110	    float*         Y1   = a.Y1  + (int64_t)pe * kM * kD;
111	    float*         dX   = a.dX  + (int64_t)pe * kM * kD;
112	    const float*   W0o  = a.W0s + (int64_t)pe * F * kD;   // [F, d]
113	    const float*   b0o  = a.b0s + (int64_t)pe * F;        // [F]
114	    const float*   W1o  = a.W1s + (int64_t)pe * kD * F;   // [d, F]
115	    float*         dW0o = a.dW0 + (int64_t)pe * F * kD;
116	    float*         db0o = a.db0 + (int64_t)pe * F;
117	    float*         dW1o = a.dW1 + (int64_t)pe * kD * F;
118	    float*         db1o = a.db1 + (int64_t)pe * kD;
119	
120	    // ── FWD: col-parallel ff0 (comm-free): Y0_own = X @ W0_own^T → fp32 via the
121	    //    production wgmma tile; bias-fold + gelu mirror the production rounding
122	    //    (pre kept bf16 like ff0pre; gact bf16 like X_gact). Reuse the publish
123	    //    slot as the [M,F] fp32 GEMM scratch (slot is M*d ≥ M*F... F ≤ d only
124	    //    when P ≥ dff/d = 4) — NOT guaranteed; use Y1 as scratch instead (M*d
125	    //    floats is too small for F>d). dG is [M,F] — use it as the fwd scratch
126	    //    (free until the backward). ──
127	    tp::tp_colparallel_fwd_tile<SG_TUNED_TILE_N>(a.X, W0o, dG, kD, F, sm.sA, sm.sB);
128	    __syncthreads();
129	    for (int idx = threadIdx.x; idx < kM * F; idx += blockDim.x) {
130	        const int j = idx % F;
131	        const float p = dG[idx] + b0o[j];                  // fp32 bias fold
132	        pre[idx] = __float2bfloat16(p);                    // ff0pre mirror
133	        G[idx]   = __float2bfloat16(dec_gelu(p));          // X_gact mirror
134	    }
135	    __syncthreads();
136	
137	    // ── FWD: row-parallel ff2 PARTIAL → publish to the symmetric slot (the
138	    //    all-reduce point ② of design §5.1). ──
139	    tp::tp_rowparallel_fwd_partial_tile<SG_TUNED_TILE_N>(
140	        tr, slot_part, G, W1o, F, kD, sm.sA, sm.sB);
141	    tr.rendezvous(bar);                                    // partials published
142	    // Fixed-order ascending-pe fp32 reduce → this PE's Y1 copy; + replicated b1.
143	    tp::tp_allreduce_sum_fixed_order(tr, slot_part, Y1, (int64_t)kM * kD,
144	                                     threadIdx.x, blockDim.x);
145	    __syncthreads();
146	    for (int idx = threadIdx.x; idx < kM * kD; idx += blockDim.x)
147	        Y1[idx] += a.b1[idx % kD];
148	    tr.rendezvous(bar);                                    // slot reusable
149	
150	    // ── BWD: row-parallel dX (comm-free): dG_own = dY1 @ W1_own. ──
151	    tp::tp_rowparallel_dx_tile<SG_TUNED_TILE_N>(a.dY1, W1o, dG, F, kD, sm.sA, sm.sB);
152	    __syncthreads();
153	    // gelu' on the ROUNDED pre (production dY_ff0 pattern), bf16 like dY_ff0.
154	    for (int idx = threadIdx.x; idx < kM * F; idx += blockDim.x)
155	        dY0[idx] = __float2bfloat16(dG[idx] * dec_gelu_grad(__bfloat162float(pre[idx])));
156	    __syncthreads();
157	
158	    // ── BWD: col-parallel dX PARTIAL → publish to the SECOND slot (the
159	    //    conjugate point ②'; distinct slot exercises multi-slot addressing). ──
160	    tp::tp_colparallel_dx_partial_tile<SG_TUNED_TILE_N>(
161	        tr, slot_n, dY0, W0o, kD, F, sm.sA, sm.sB);
162	    tr.rendezvous(bar);
163	    tp::tp_allreduce_sum_fixed_order(tr, slot_n, dX, (int64_t)kM * kD,
164	                                     threadIdx.x, blockDim.x);
165	    tr.rendezvous(bar);
166	
167	    // ── dW/db shards (exact-slice property; ascending-m fp32, single owner per
168	    //    element — the P2 determinism contract). dW0_own[i,k] = Σ_m dY0[m,i]·X[m,k];
169	    //    dW1_own[j,c] = Σ_m dY1[m,j]·G_own[m,c]; db0_own[i] = Σ_m dY0[m,i];
170	    //    db1[j] = Σ_m dY1[m,j] (replicated: every PE computes the identical value). ──
171	    for (int idx = threadIdx.x; idx < F * kD; idx += blockDim.x) {
172	        const int i = idx / kD, k = idx % kD;
173	        float acc = 0.0f;
174	        for (int m = 0; m < kM; ++m)
175	            acc += __bfloat162float(dY0[(int64_t)m * F + i]) * __bfloat162float(a.X[(int64_t)m * kD + k]);
176	        dW0o[idx] = acc;
177	    }
178	    for (int idx = threadIdx.x; idx < kD * F; idx += blockDim.x) {
179	        const int j = idx / F, c = idx % F;
180	        float acc = 0.0f;
181	        for (int m = 0; m < kM; ++m)
182	            acc += __bfloat162float(a.dY1[(int64_t)m * kD + j]) * __bfloat162float(G[(int64_t)m * F + c]);
183	        dW1o[idx] = acc;
184	    }
185	    for (int i = threadIdx.x; i < F; i += blockDim.x) {
186	        float acc = 0.0f;
187	        for (int m = 0; m < kM; ++m) acc += __bfloat162float(dY0[(int64_t)m * F + i]);
188	        db0o[i] = acc;
189	    }
190	    for (int j = threadIdx.x; j < kD; j += blockDim.x) {
191	        float acc = 0.0f;
192	        for (int m = 0; m < kM; ++m) acc += __bfloat162float(a.dY1[(int64_t)m * kD + j]);
193	        db1o[j] = acc;
194	    }
195	}
196	
197	// ─────────────────────────────────────────────────────────────────────────
198	//  REFERENCE kernel (1 CTA): (i) the UNSHARDED pair with the same wgmma tiles
199	//  (full-K contraction — the tol-comparison baseline), and (ii) the SERIAL
200	//  CHUNKED-ORDER reference — per-shard partial GEMMs (identical inputs/code as
201	//  the TP kernel) summed ascending-pe in fp32 with the same element loop as
202	//  tp_allreduce_sum_fixed_order ⇒ must equal the TP+transport result BIT-EXACT.
203	// ─────────────────────────────────────────────────────────────────────────
204	struct TpRefArgs {
205	    const __nv_bfloat16* X; const __nv_bfloat16* dY1;
206	    const float* W0; const float* b0; const float* W1; const float* b1;  // FULL
207	    const float* W0s; const float* b0s; const float* W1s;                // shards
208	    __nv_bfloat16* pre_full;  // [M, dff]
209	    __nv_bfloat16* G_full;    // [M, dff]
210	    __nv_bfloat16* dY0_full;  // [M, dff]
211	    float* scratch_f;         // [M, dff] fp32 general
212	    __nv_bfloat16* pre_o;     // [M, dff/P] per-shard recompute scratch
213	    __nv_bfloat16* G_o;       // [M, dff/P]
214	    __nv_bfloat16* dY0_o;     // [M, dff/P]
215	    float* part;              // [M, d] one shard's partial
216	    float* Y1_ref; float* dX_ref;          // [M, d] unsharded
217	    float* dW0_ref; float* db0_ref;        // [dff, d], [dff]
218	    float* dW1_ref; float* db1_ref;        // [d, dff], [d]
219	    float* Y1_chunked; float* dX_chunked;  // [M, d] serial chunked-order
220	    int P;
221	};
222	
223	__global__ void __launch_bounds__(kBlk)
224	tp_reference_kernel(TpRefArgs a) {
225	    __shared__ TpSmem sm;
226	    const int P = a.P;
227	    const int F = kDff / P;
228	
229	    // ── (i) UNSHARDED: ff0 → gelu → ff2 (+b1); bwd dG → dY0 → dX; dW/db. ──
230	    dectc::dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(a.X, a.W0, a.scratch_f, kD, kDff, sm.sA, sm.sB);
231	    __syncthreads();
232	    for (int idx = threadIdx.x; idx < kM * kDff; idx += blockDim.x) {
233	        const int j = idx % kDff;
234	        const float p = a.scratch_f[idx] + a.b0[j];
235	        a.pre_full[idx] = __float2bfloat16(p);
236	        a.G_full[idx]   = __float2bfloat16(dec_gelu(p));
237	    }
238	    __syncthreads();
239	    dectc::dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(a.G_full, a.W1, a.Y1_ref, kDff, kD, sm.sA, sm.sB);
240	    __syncthreads();
241	    for (int idx = threadIdx.x; idx < kM * kD; idx += blockDim.x)
242	        a.Y1_ref[idx] += a.b1[idx % kD];
243	    __syncthreads();
244	    dectc::dectc_gemm_dx_f32<SG_TUNED_TILE_N>(a.dY1, a.W1, a.scratch_f, kDff, kD, sm.sA, sm.sB);
245	    __syncthreads();
246	    for (int idx = threadIdx.x; idx < kM * kDff; idx += blockDim.x)
247	        a.dY0_full[idx] = __float2bfloat16(
248	            a.scratch_f[idx] * dec_gelu_grad(__bfloat162float(a.pre_full[idx])));
249	    __syncthreads();
250	    dectc::dectc_gemm_dx_f32<SG_TUNED_TILE_N>(a.dY0_full, a.W0, a.dX_ref, kD, kDff, sm.sA, sm.sB);
251	    __syncthreads();
252	    for (int idx = threadIdx.x; idx < kDff * kD; idx += blockDim.x) {
253	        const int i = idx / kD, k = idx % kD;
254	        float acc = 0.0f;
255	        for (int m = 0; m < kM; ++m)
256	            acc += __bfloat162float(a.dY0_full[(int64_t)m * kDff + i]) * __bfloat162float(a.X[(int64_t)m * kD + k]);
257	        a.dW0_ref[idx] = acc;
258	    }
259	    for (int idx = threadIdx.x; idx < kD * kDff; idx += blockDim.x) {
260	        const int j = idx / kDff, c = idx % kDff;
261	        float acc = 0.0f;
262	        for (int m = 0; m < kM; ++m)
263	            acc += __bfloat162float(a.dY1[(int64_t)m * kD + j]) * __bfloat162float(a.G_full[(int64_t)m * kDff + c]);
264	        a.dW1_ref[idx] = acc;
265	    }
266	    for (int i = threadIdx.x; i < kDff; i += blockDim.x) {
267	        float acc = 0.0f;
268	        for (int m = 0; m < kM; ++m) acc += __bfloat162float(a.dY0_full[(int64_t)m * kDff + i]);
269	        a.db0_ref[i] = acc;
270	    }
271	    for (int j = threadIdx.x; j < kD; j += blockDim.x) {
272	        float acc = 0.0f;
273	        for (int m = 0; m < kM; ++m) acc += __bfloat162float(a.dY1[(int64_t)m * kD + j]);
274	        a.db1_ref[j] = acc;
275	    }
276	    __syncthreads();
277	
278	    // ── (ii) SERIAL CHUNKED-ORDER: ascending-pe accumulation of per-shard
279	    //    partials computed with the IDENTICAL shard GEMM calls the TP kernel
280	    //    makes. acc starts at 0 and adds partials in pe order — the same
281	    //    arithmetic as tp_allreduce_sum_fixed_order ⇒ bit-exact vs TP. ──
282	    for (int idx = threadIdx.x; idx < kM * kD; idx += blockDim.x) {
283	        a.Y1_chunked[idx] = 0.0f; a.dX_chunked[idx] = 0.0f;
284	    }
285	    __syncthreads();
286	    for (int pe = 0; pe < P; ++pe) {                      // ASCENDING pe
287	        const float* W0o = a.W0s + (int64_t)pe * F * kD;
288	        const float* b0o = a.b0s + (int64_t)pe * F;
289	        const float* W1o = a.W1s + (int64_t)pe * kD * F;
290	        // recompute this shard's pre/G/dY0 (same code path as the TP kernel).
291	        tp::tp_colparallel_fwd_tile<SG_TUNED_TILE_N>(a.X, W0o, a.scratch_f, kD, F, sm.sA, sm.sB);
292	        __syncthreads();
293	        for (int idx = threadIdx.x; idx < kM * F; idx += blockDim.x) {
294	            const int j = idx % F;
295	            const float p = a.scratch_f[idx] + b0o[j];
296	            a.pre_o[idx] = __float2bfloat16(p);
297	            a.G_o[idx]   = __float2bfloat16(dec_gelu(p));
298	        }
299	        __syncthreads();
300	        dectc::dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(a.G_o, W1o, a.part, F, kD, sm.sA, sm.sB);
301	        __syncthreads();
302	        for (int idx = threadIdx.x; idx < kM * kD; idx += blockDim.x)
303	            a.Y1_chunked[idx] += a.part[idx];             // ascending-pe fp32 sum
304	        __syncthreads();
305	        dectc::dectc_gemm_dx_f32<SG_TUNED_TILE_N>(a.dY1, W1o, a.scratch_f, F, kD, sm.sA, sm.sB);
306	        __syncthreads();
307	        for (int idx = threadIdx.x; idx < kM * F; idx += blockDim.x)
308	            a.dY0_o[idx] = __float2bfloat16(
309	                a.scratch_f[idx] * dec_gelu_grad(__bfloat162float(a.pre_o[idx])));
310	        __syncthreads();
311	        dectc::dectc_gemm_dx_f32<SG_TUNED_TILE_N>(a.dY0_o, W0o, a.part, kD, F, sm.sA, sm.sB);
312	        __syncthreads();
313	        for (int idx = threadIdx.x; idx < kM * kD; idx += blockDim.x)
314	            a.dX_chunked[idx] += a.part[idx];
315	        __syncthreads();
316	    }
317	    // + b1 on the chunked fwd (after the sum, matching the TP kernel's order).
318	    for (int idx = threadIdx.x; idx < kM * kD; idx += blockDim.x)
319	        a.Y1_chunked[idx] += a.b1[idx % kD];
320	}
321	
322	// ─────────────────────────────────────────────────────────────────────────
323	//  Host plumbing.
324	// ─────────────────────────────────────────────────────────────────────────
325	#define CHK(t, n, len) \
326	    TORCH_CHECK((t).is_cuda() && (t).scalar_type() == at::kFloat && (t).is_contiguous() \
327	                && (t).numel() == (len), n " must be CUDA fp32 contiguous of numel ", (int64_t)(len))
328	
329	void tp_loopback_run(int64_t P_,
330	                     at::Tensor X, at::Tensor dY1,
331	                     at::Tensor W0s, at::Tensor b0s, at::Tensor W1s, at::Tensor b1,
332	                     at::Tensor Y1, at::Tensor dX,
333	                     at::Tensor dW0, at::Tensor db0, at::Tensor dW1, at::Tensor db1) {
334	    const int P = (int)P_;
335	    TORCH_CHECK(P >= 2 && kDff % P == 0 && (kDff / P) % 16 == 0,
336	                "TP degree must divide dff with 16 | dff/P (wgmma K-step); got P=", P);
337	    const int F = kDff / P;
338	    CHK(X, "X", (int64_t)kM * kD); CHK(dY1, "dY1", (int64_t)kM * kD);
339	    CHK(W0s, "W0s", (int64_t)kDff * kD); CHK(b0s, "b0s", (int64_t)kDff);
340	    CHK(W1s, "W1s", (int64_t)kD * kDff); CHK(b1, "b1", (int64_t)kD);
341	    CHK(Y1, "Y1", (int64_t)P * kM * kD); CHK(dX, "dX", (int64_t)P * kM * kD);
342	    CHK(dW0, "dW0", (int64_t)kDff * kD); CHK(db0, "db0", (int64_t)kDff);
