439	// Pack the dense per-rank shards on CPU using the tp_layer.cuh index maps (the
440	// SINGLE source of the pack arithmetic — no Python re-derivation). Returns
441	// (W0s [dff,d], b0s [dff], W1s [d,dff]) as the per-rank dense concatenations.
442	std::vector<at::Tensor> tp_pack_pair_shards(int64_t P_, at::Tensor W0, at::Tensor b0,
443	                                            at::Tensor W1) {
444	    const int P = (int)P_;
445	    TORCH_CHECK(P >= 2 && kDff % P == 0, "P must divide dff=", kDff);
446	    TORCH_CHECK(!W0.is_cuda() && !b0.is_cuda() && !W1.is_cuda(),
447	                "pack expects CPU fp32 tensors (move to CUDA after packing)");
448	    TORCH_CHECK(W0.scalar_type() == at::kFloat && W0.is_contiguous() && W0.numel() == (int64_t)kDff * kD);
449	    TORCH_CHECK(b0.scalar_type() == at::kFloat && b0.is_contiguous() && b0.numel() == (int64_t)kDff);
450	    TORCH_CHECK(W1.scalar_type() == at::kFloat && W1.is_contiguous() && W1.numel() == (int64_t)kD * kDff);
451	    const int F = kDff / P;
452	    at::Tensor W0s = at::empty_like(W0), b0s = at::empty_like(b0), W1s = at::empty_like(W1);
453	    const float* w0 = W0.data_ptr<float>(); float* w0s = W0s.data_ptr<float>();
454	    const float* b0p = b0.data_ptr<float>(); float* b0sp = b0s.data_ptr<float>();
455	    const float* w1 = W1.data_ptr<float>(); float* w1s = W1s.data_ptr<float>();
456	    for (int r = 0; r < P; ++r) {
457	        int lo, hi;
458	        tp::tp_own_range(kDff, P, r, &lo, &hi);            // Col split rows of W0
459	        for (int i = 0; i < F; ++i) {
460	            const int fi = tp::tp_col_full_row(lo, i);
461	            for (int k = 0; k < kD; ++k)
462	                w0s[((int64_t)r * F + i) * kD + k] = w0[(int64_t)fi * kD + k];
463	            b0sp[(int64_t)r * F + i] = b0p[fi];
464	        }
465	        for (int j = 0; j < kD; ++j)                       // Row split cols of W1
466	            for (int c = 0; c < F; ++c) {
467	                const int fc = tp::tp_row_full_col(lo, c);
468	                w1s[((int64_t)r * kD + j) * F + c] = w1[(int64_t)j * kDff + fc];
469	            }
470	    }
471	    return {W0s, b0s, W1s};
472	}
